#!/usr/bin/env python3
from pathlib import Path

runtime = Path("tools/rll_pipeline_fase24_1_runtime.py")
tests = Path("tests/test_rll_pipeline_fase24_1_runtime.py")
s = runtime.read_text(encoding="utf-8")

s = s.replace(
    "ORIGINAL_WRITE_CHECKSUMS = core.write_checksums\n",
    "ORIGINAL_WRITE_CHECKSUMS = core.write_checksums\nORIGINAL_RUN_STEP = core.run_step\n",
)

old_step13 = '''    _replace_step(13, commands=(command(\n        "bash", "-lc", f"cd scripts/pantheon && {py} run_rll_vs_pantheon.py",\n        requires=("scripts/pantheon/run_rll_vs_pantheon.py", "scripts/pantheon/load_pantheon.py", "scripts/pantheon/models.py"),\n    ),), candidates=())'''
new_step13 = '''    _replace_step(13, commands=(command(\n        "bash", "-lc",\n        f"mkdir -p artifacts/linear/current_run && "\n        f"PYTHONPATH=products/rll-evidence-runner/src {py} -m rll_evidence.pantheon_fit_ascii "\n        "--catalog data/real/cosmology/pantheon_plus/Pantheon+_Data/4_DISTANCES_AND_COVAR/Pantheon+SH0ES.dat "\n        "--covariance data/real/cosmology/pantheon_plus/Pantheon+_Data/4_DISTANCES_AND_COVAR/Pantheon+SH0ES_STAT+SYS.cov "\n        "--output artifacts/linear/current_run/pantheon_fit_result.json "\n        "--seeds 11,23,37,53,71 --maxiter 250 --integration-points 4096 --z-min 0.01",\n        requires=(\n            "products/rll-evidence-runner/src/rll_evidence/pantheon_fit_ascii.py",\n            "data/real/cosmology/pantheon_plus/Pantheon+_Data/4_DISTANCES_AND_COVAR/Pantheon+SH0ES.dat",\n            "data/real/cosmology/pantheon_plus/Pantheon+_Data/4_DISTANCES_AND_COVAR/Pantheon+SH0ES_STAT+SYS.cov",\n            "data/real/cosmology/pantheon_plus/Pantheon+_Data/4_DISTANCES_AND_COVAR/Pantheon+SH0ES_STAT+SYS.cov.sha256",\n        ),\n    ),), candidates=())'''
if old_step13 not in s:
    raise SystemExit("step13 source contract not found")
s = s.replace(old_step13, new_step13)

start = s.index("def materialize_pantheon_metrics() -> None:\n")
end = s.index("\n\ndef _copy_if_present", start)
new_pantheon = '''def materialize_pantheon_metrics() -> None:\n    log = LOGS / "step13_pantheon_fit.log"\n    result = CURRENT_RUN / "pantheon_fit_result.json"\n    output = RESULTS / "pantheon_plus_resultado_real.json"\n    payload: dict[str, object] = {\n        "schema_version": "rll.pantheon.current-run.v2",\n        "generated_at": datetime.now(timezone.utc).isoformat(),\n        "claim_allowed": False,\n        "source_log": core.rel(log),\n        "source_result": core.rel(result),\n        "delta_aic": None,\n        "chi2_red_rll": None,\n        "models": {},\n    }\n    models: dict[str, dict[str, float]] = {}\n    if result.is_file():\n        try:\n            raw = json.loads(result.read_text(encoding="utf-8"))\n        except (OSError, json.JSONDecodeError):\n            raw = {}\n        rows = raw.get("rows", []) if isinstance(raw, dict) else []\n        if isinstance(rows, list):\n            for row in rows:\n                if not isinstance(row, dict):\n                    continue\n                name = str(row.get("model", "")).strip()\n                if not name:\n                    continue\n                try:\n                    chi2 = float(row["chi2"]); aic = float(row["AIC"])\n                    dof = float(row["dof"]); k = float(row["k"])\n                except (KeyError, TypeError, ValueError):\n                    continue\n                models[name] = {"chi2": chi2, "k": k, "dof": dof,\n                    "chi2_red": chi2 / dof if dof > 0 else float("nan"), "aic": aic}\n        baseline = next((v for k, v in models.items() if "lcdm" in k.lower()), None)\n        candidate = next((v for k, v in models.items() if "rll" in k.lower()), None)\n        if baseline is not None and candidate is not None:\n            payload["state"] = "VERIFIED"\n            payload["delta_aic"] = candidate["aic"] - baseline["aic"]\n            payload["chi2_red_rll"] = candidate["chi2_red"]\n            payload["models"] = models\n            output.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n            return\n    if log.is_file():\n        pattern = re.compile(r"^(lcdm|cpl|rll_original|rll_optionA)\\s+([0-9.eE+-]+)\\s+(\\d+)\\s+([0-9.eE+-]+)\\s+([0-9.eE+-]+)\\s*$", re.MULTILINE)\n        for match in pattern.finditer(log.read_text(encoding="utf-8", errors="replace")):\n            name, chi2, k, reduced, aic = match.groups()\n            models[name] = {"chi2": float(chi2), "k": float(k), "chi2_red": float(reduced), "aic": float(aic)}\n    if "lcdm" in models and "rll_original" in models:\n        payload["state"] = "VERIFIED"\n        payload["delta_aic"] = models["rll_original"]["aic"] - models["lcdm"]["aic"]\n        payload["chi2_red_rll"] = models["rll_original"]["chi2_red"]\n    else:\n        payload["state"] = "TOKEN_VAZIO"\n        payload["reason"] = "LCDM/RLL current-run rows not parsed"\n    payload["models"] = models\n    output.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n'''
s = s[:start] + new_pantheon + s[end:]

old_fcos04 = '''        "F-COS-04": ("ln(B10)", "> -5", find_csv_metric((("results/structure_d/bayes_factor_interpretation.csv", ("log_bayes_factor", "ln_B10", "log_evidence_ratio")),))),'''
new_fcos04 = '''        "F-COS-04": ("ln(B10)", "> -5", find_json_metric((\n            ("artifacts/linear/current_run/real_bic_proxy_status.json", ("log_bayes_factor",)),\n        ))),'''
if old_fcos04 not in s:
    raise SystemExit("F-COS-04 source not found")
s = s.replace(old_fcos04, new_fcos04)

marker = "def gate_decision(mode: str, results: Sequence[core.StepResult], contract: dict[str, object]) -> dict[str, object]:\n"
wrapper = '''def run_step(step: core.Step, selected_phases: set[int], mode: str) -> core.StepResult:\n    result = ORIGINAL_RUN_STEP(step, selected_phases, mode)\n    if step.number == 21 and result.status == "FAIL" and result.exit_code == 3:\n        status_path = CURRENT_RUN / "real_bayes_inference_status.json"\n        try:\n            payload = json.loads(status_path.read_text(encoding="utf-8"))\n        except (OSError, json.JSONDecodeError):\n            payload = {}\n        if payload.get("state") == "TOKEN_VAZIO":\n            return replace(result, status="TOKEN_VAZIO", exit_code=None,\n                detail="inferência Bayes real não materializada; estado auditável TOKEN_VAZIO")\n    return result\n\n\n'''
if marker not in s:
    raise SystemExit("gate marker not found")
s = s.replace(marker, wrapper + marker)
s = s.replace("    core.build_contract = build_contract\n", "    core.run_step = run_step\n    core.build_contract = build_contract\n")
runtime.write_text(s, encoding="utf-8")

t = tests.read_text(encoding="utf-8")
if "test_pantheon_step_uses_canonical_full_covariance_runner" not in t:
    t += '''\n\ndef test_pantheon_step_uses_canonical_full_covariance_runner() -> None:\n    runtime = load_runtime()\n    spec = step(runtime, 13).commands[0]\n    joined = " ".join(spec.argv)\n    assert "rll_evidence.pantheon_fit_ascii" in joined\n    assert "Pantheon+SH0ES_STAT+SYS.cov" in joined\n    assert "scripts/pantheon/models.py" not in spec.requires\n    assert "pantheon_fit_result.json" in joined\n\n\ndef test_pantheon_metrics_are_read_from_current_full_covariance_result(tmp_path, monkeypatch) -> None:\n    runtime = load_runtime()\n    results = tmp_path / "results" / "linear"; logs = tmp_path / "logs" / "linear"\n    current = tmp_path / "artifacts" / "linear" / "current_run"\n    results.mkdir(parents=True); logs.mkdir(parents=True); current.mkdir(parents=True)\n    (current / "pantheon_fit_result.json").write_text(json.dumps({"rows": [\n        {"model": "LCDM_pantheon_full", "chi2": 100.0, "AIC": 108.0, "k": 4, "dof": 96},\n        {"model": "RLL_pantheon_full", "chi2": 101.0, "AIC": 115.0, "k": 7, "dof": 93}]}), encoding="utf-8")\n    monkeypatch.setattr(runtime, "ROOT", tmp_path); monkeypatch.setattr(runtime, "RESULTS", results)\n    monkeypatch.setattr(runtime, "LOGS", logs); monkeypatch.setattr(runtime, "CURRENT_RUN", current)\n    runtime.materialize_pantheon_metrics()\n    payload = json.loads((results / "pantheon_plus_resultado_real.json").read_text(encoding="utf-8"))\n    assert payload["state"] == "VERIFIED"; assert payload["delta_aic"] == 7.0\n    assert payload["chi2_red_rll"] == 101.0 / 93.0\n\n\ndef test_real_bayes_absence_is_classified_as_token_vazio_step(tmp_path, monkeypatch) -> None:\n    runtime = load_runtime(); current = tmp_path / "artifacts" / "linear" / "current_run"; current.mkdir(parents=True)\n    (current / "real_bayes_inference_status.json").write_text(json.dumps({"state": "TOKEN_VAZIO"}), encoding="utf-8")\n    monkeypatch.setattr(runtime, "CURRENT_RUN", current)\n    base = runtime.core.StepResult(21, "joint_mcmc_p0", 3, "test", True, "FAIL", 3, 1.0, "cmd", "exit 3", "log")\n    monkeypatch.setattr(runtime, "ORIGINAL_RUN_STEP", lambda *args, **kwargs: base)\n    result = runtime.run_step(runtime.core.Step(21, "joint_mcmc_p0", 3, "test", True), {3}, "completo")\n    assert result.status == "TOKEN_VAZIO"; assert result.exit_code is None\n\n\ndef test_fcos04_reads_materialized_real_bic_status(tmp_path, monkeypatch) -> None:\n    runtime = load_runtime(); status = tmp_path / "artifacts" / "linear" / "current_run" / "real_bic_proxy_status.json"\n    status.parent.mkdir(parents=True); status.write_text(json.dumps({"log_bayes_factor": -5.668269}), encoding="utf-8")\n    monkeypatch.setattr(runtime, "ROOT", tmp_path)\n    metric = runtime.find_json_metric((("artifacts/linear/current_run/real_bic_proxy_status.json", ("log_bayes_factor",)),))\n    assert metric["state"] == "VERIFIED"; assert runtime.evaluate("F-COS-04", metric["value"]) == "FAIL"\n'''
tests.write_text(t, encoding="utf-8")
print("follow-up patch applied")
